input.content:
extends Node

signal coin_changed(new_count: int)

var _count: int = 0
const SAVE_PATH = "user://save.json"

func _ready():
	load_game()

func add_coin():
	_count += 1
	save()
	coin_changed.emit(_count)

func get_count() -> int:
	return _count

func save():
	var file = FileAccess.open(SAVE_PATH, FileAccess.WRITE)
	if file:
		var data = {"count": _count}
		file.store_string(JSON.stringify(data))

func load_game():
	if not FileAccess.file_exists(SAVE_PATH):
		return

	var file = FileAccess.open(SAVE_PATH, FileAccess.READ)
	if file:
		var json_string = file.get_as_text()
		var json = JSON.new()
		var error = json.parse(json_string)
		if error == OK:
			var data = json.data
			if typeof(data) == TYPE_DICTIONARY:
				_count = data.get("count", 0)
				coin_changed.emit(_count)

func _notification(what):
	if what == NOTIFICATION_WM_CLOSE_REQUEST:
		save()

extends CharacterBody2D

const SPEED = 300.0

func _physics_process(_delta):
	var direction_x = Input.get_axis("ui_left", "ui_right")
	var direction_y = Input.get_axis("ui_up", "ui_down")

	velocity = Vector2(direction_x, direction_y).normalized() * SPEED
	move_and_slide()

extends CanvasLayer

@onready var label = $Label

func _ready():
	Inventory.coin_changed.connect(_on_coin_changed)
	_on_coin_changed(Inventory.get_count())

func _on_coin_changed(new_count: int):
	label.text = "Coins: " + str(new_count)
